# Surah Al-Baqarah (chapter 2) — part 2: ayat 11-20 (IDs 18-27)
SURAH = 2

ENTRIES = {
18: (
"اور جب ان سے کہا جاتا ہے کہ زمین میں فساد نہ کرو تو کہتے ہیں ہم تو اصلاح کرنے والے ہیں۔",
"""۱۔ منافقین کی ایک خاص پہچان بیان ہوئی: جب ان سے کہا جائے کہ زمین میں فساد پھیلانا چھوڑو تو جواب دیتے ہیں کہ ہم تو صرف اصلاح کر رہے ہیں۔
۲۔ فساد فی الارض کا پہلو بہت وسیع ہے — شرک، ظلم، ناانصافی، آپس میں ضد، دشمنی، معاشی استحصال، شرابی، جوئے اور بدکاری کی حوصلہ افزائی سب اسی میں آتے ہیں۔
۳۔ منافق سب سے پہلے خود کو مصلح قرار دے کر اپنے جرم کو چھپانے کی کوشش کرتا ہے — نیت کی سفیدی کا دعویٰ اور عمل میں سیاہی۔
۴۔ یہی ہر دور کا فریب ہے: ظلم کو نظم و ضوابط کا نام، بے حیائی کو آزادی کا نام، فرقہ واریت کو خدمت کا نام دے کر پیش کیا جاتا ہے۔
۵۔ عملی سبق: کسی کام کو نام دینے سے پہلے اس کے نتائج دیکھیں — جس کا نتیجہ فساد ہو وہ مصلح نہیں کہلا سکتا۔ خود بھی احتساب کریں کہ ضمیراً نیک مگر عملاً برباد تو نہیں۔"""
),
19: (
"خبردار! بے شک یہی لوگ اصل فساد کرنے والے ہیں، مگر انہیں شعور نہیں۔",
"""۱۔ اللہ تعالیٰ منافقین کے دعوے کا بالکل الٹ فیصلہ سناتا ہے: درحقیقت یہی اصل مفسد ہیں۔
۲۔ ’’أَلَا‘‘ (خبردار) — یہ کلمہ سننے والے کو چوکنا کرنے کے لیے آتا ہے؛ یہاں سننے والے مسلمانوں کو منافقوں کی حقیقت سے آگاہ کیا جا رہا ہے۔
۳۔ ’’وَلَٰكِنْ لَّا يَشْعُرُونَ‘‘ — مگر انہیں خود اپنی حالت کا احساس نہیں۔ خود فریبی منافقت کی روح ہے — وہ سمجھتے ہیں کہ وہ نفع بخش منصوبہ بنا رہے ہیں جبکہ وہ صرف بربادی کے بیج بو رہے ہیں۔
۴۔ یہاں نکتۂ اہم یہ ہے کہ فساد کا سزا پانے کے لیے فسادی کا خود شعور رکھنا ضروری نہیں — نتیجہ اسی کے دامن میں آتا ہے جو بیج بوئے۔
۵۔ اصلاحِ معاشرہ کا کام کرنے والے کو پہلے اپنے دل کی ٹیسٹ کرنی چاہیے — کیا واقعی نیت اللہ کی رضا ہے یا شہرت و مفاد؟"""
),
20: (
"اور جب ان سے کہا جاتا ہے کہ (سچے دل سے) ایمان لاؤ جیسا کہ لوگ ایمان لائے، تو کہتے ہیں کیا ہم بیوقوفوں کی طرح ایمان لائیں؟ — خبردار! دراصل یہی خود بیوقوف ہیں مگر انہیں سمجھ نہیں۔",
"""۱۔ منافقین سے کہا گیا کہ جس طرح باقاعدہ اہل ایمان سچے ہو کر ایمان لائے ہیں، تم بھی وہی تعلیم قبول کرو۔ جواب ملا: کیا ہم بھی بیوقوفوں (سفیہوں) کی طرح ایمان لائیں؟
۲۔ یعنی منافق اپنی ہوشیاری پر غرور کرتا ہے کہ وہ دوہرا کھیل کھیل رہا ہے — ظاہر میں مسلمان، باطن میں انکار — اور مؤمنوں کو سادہ لوح سمجھتا ہے۔
۳۔ ’’أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ‘‘ — خبردار! حقیقت میں یہی بے وقوف ہیں۔ نکتہ یہ ہے کہ انجام اور عاقبت سمجھے بغیر دنیا کا ذاتی فائدہ تولا، وہ اجر کھویا جس کا حساب قیامت میں ہوگا — یہی سب سے بڑی کم عقلی ہے۔
۴۔ ’’وَلَٰكِنْ لَّا يَعْلَمُونَ‘‘ — اور انہیں یہ سمجھ نہیں کہ وہ بے وقوف کہلائے جا رہے ہیں۔ خود فریبی کا انجام یہی ہے کہ آدمی کو اپنی جہالت نظر نہیں آتی۔
۵۔ بصیرت اور ہوشیاری کا اصل پیمانہ اللہ کے نزدیک ایمان ہے — دنیاوی چالاکیوں سے عقل کی پہچان نہیں ہوتی۔
۶۔ عملی سبق: خدا کی راہ میں ایمان کو سادگی نہ سمجھیں؛ سب سے زبردست عقل وہ ہے جو آخرت کو محفوظ کرے۔"""
),
21: (
"اور جب وہ ایمان والوں سے ملتے ہیں تو کہتے ہیں ہم ایمان لائے، اور جب اپنے شیطانوں کے ساتھ تنہائی میں ہوتے ہیں تو کہتے ہیں ہم تمہارے ساتھ ہیں؛ ہم تو محض مذاق اڑا رہے ہیں۔",
"""۱۔ منافقین کا دوہرا کردار بیان ہوا: مؤمنوں سے مل کر کہتے ہیں ہم ایمان لائے؛ اپنے سرداروں (شیاطین — یعنی شر اور شرارتی لوگوں) کے پاس جا کر کہتے ہیں ہم تمہارے ہی ساتھ ہیں۔
۲۔ ’’شَیَاطِینِہِمْ‘‘ سے مراد وہ سرکش لوگ ہیں جن کے ساتھ منافقین گہری دوستی رکھتے ہیں — شر کی گٹھ جوڑ۔ یہاں ’’شیطان‘‘ انسان کے بھی ہوتے ہیں (بدنیت رہنما)۔
۳۔ ’’إِنَّمَا نَحْنُ مُسْتَهْزِئُونَ‘‘ — ہم تو بس مذاق اڑا رہے ہیں۔ یعنی اپنے کفر اور منافقت کو انہوں نے کھیل بنا رکھا تھا — اللہ اور رسول ﷺ کی تعلیمات کو کھیل سمجھنا سب سے بڑا گستاخی ہے۔
۴۔ اس آیت سے واضح ہے کہ منافق کبھی ایک صورت پر قائم نہیں رہتا — اس کی وفاداری موقع کے ساتھ بدلتی ہے؛ یہی اس کی پہچان ہے۔
۵۔ عملی سبق: دغا باز دوستی اور ہمدردی اندر سے جانچیں — آدمی کی اصل وہی ہے جو خلوت اور سختی کے وقت ظاہر ہو، نہ وہ جو سلام میں دکھائی دے۔"""
),
22: (
"اللہ ان سے مذاق کرتا ہے اور انہیں ان کی سرکشی میں ڈھیل دیتا ہے، وہ بھٹکتے پھرتے ہیں۔",
"""۱۔ منافقین اللہ اور اس کے دین سے مذاق اڑاتے رہے؛ جواب میں اللہ نے انہیں انہیں کی حال پر چھوڑ دیا — یہی ان کا انجام ہے۔ ’’اللّٰہُ يَسْتَهْزِئُ بِهِمْ‘‘ یعنی اللہ کا مذاق یہ ہے کہ انہیں ڈھیل دیتا ہے جبکہ وہ اپنی ہلاکت کی طرف بڑھ رہے ہیں۔
۲۔ ’’يَمُدُّهُمْ فِي طُغْيَانِهِمْ‘‘ — سرکشی میں مزید ڈھیل۔ قرآن کی بار بار یہ سنت ہے: ظالم کا غرور بڑھتے بڑھتے ہلاکت تک پہنچ جاتا ہے اللہ ظالموں کو ڈھیل دیتا ہے مگر اس کا نظام ظالموں کو ہمیشہ کے لیے نہیں چھوڑتا۔
۳۔ ’’يَعْمَهُونَ‘‘ — وہ بھٹکتے پھرتے ہیں؛ نہ سمت، نہ منزل۔ یہ بھٹکن انسان کی پیدا کردہ ہے — بار بار حق ٹھکرانے کے بعد اللہ اس کے خودساختہ راستے پر چلنے دیتا ہے۔
۴۔ نکتہ: ڈھیل کا ملنا غصے کی نشانی ہے، انعام کی نہیں۔ جو بارش کے نیچے بھیگ کر بھی خشک رہتا ہے اسے بارش کا دوش نہیں۔
۵۔ عملی سبق: خدا کی عطا (سہولت، آخرت کا کسی گناہ پر فوراً اپکڑ نہ ہونا) کو گناہ کا اجازت نامہ نہ سمجھیں — یہ محض مہلت ہے نہ کہ بخشش۔"""
),
23: (
"یہی وہ لوگ ہیں جنہوں نے ہدایت کے بدلے گمراہی خرید لی، تو ان کی تجارت میں نفع نہ ہوا اور نہ وہ ہدایت پانے والے بنے۔",
"""۱۔ منافقین کی مکمل تصویر ایک مثال میں بیان کی گئی: انہوں نے سودے باز کی طرح ہدایت کی چیز کو پھینک دیا اور گمراہی کا سامان خریدا — سودا انہیں نقصان دے گیا۔
۲۔ ’’اِشْتَرَوُا الضَّلَالَةَ بِالْهُدٰی‘‘ — ہدایت دے کر گمراہی خریدنا۔ اصل میں ہدایت مفت ملتی ہے، مگر منافق نے اپنی روش سے اسے گنوا دیا۔
۳۔ ’’فَمَا رَبِحَتْ تِّجَارَتُهُمْ‘‘ — ان کی تجارت میں نفع نہ ہوا۔ دنیا کا کاروبار تو شاید پلٹ بھی جائے، مگر آخرت کا سودا نقصان پر نقصان ہے۔
۴۔ ’’وَمَا كَانُوا مُهْتَدِينَ‘‘ — اور وہ ہدایت پانے والوں میں شامل ہی نہ تھے۔ یعنی ان کا پورا سفر ہدایت سے خالی رہا۔
۵۔ تجارت کی یہ مثال سمجھاتی ہے کہ ایمان ایک سرمایہ ہے — اسے ضائع کرنا خسارہ ہے، اور اس کی نگہداشت ہی سب سے بڑی پونجی ہے۔
۶۔ عملی سبق: ہر فیصلہ کرتے وقت آخری حساب کا سوال کریں — کیا اس عمل سے ایمان مضبوط ہوگا یا کمزور؟"""
),
24: (
"ان کی مثال اس شخص کی سی ہے جس نے آگ سلگائی — پھر جب اس نے اس کے اردگرد روشن کیا تو اللہ نے ان کا نور چھین لیا اور انہیں اندھیروں میں چھوڑ دیا جہاں وہ دیکھ نہیں سکتے۔",
"""۱۔ منافقین کی کیفیت کے لیے ایک واضح مثال دی گئی: ایک شخص آگ سلگاتا ہے؛ روشنی پھیلتے ہی اچانک سیاہ گھٹا اس کا نور لے جاتی ہے اور وہ اندھیروں میں رہ جاتا ہے۔
۲۔ روشنی وہ وقتی ایمان تھا جو منافق نے ظاہر میں اختیار کیا (یا جو دلائل سن کر تھوڑی دیر روشن رہا) — اور اندھیرا وہ نفاق ہے جو ان کے اندر تھا۔
۳۔ ’’ذَهَبَ اللّٰہُ بِنُوْرِہِمْ‘‘ — اللہ نے ان کا نور چھین لیا۔ یعنی وہی ایمان کی چمک جو روشنی دکھا رہی تھی، اندرونی نفاق کی وجہ سے چھن گئی۔ یہاں موقع پر اللہ کی ہٹا دینے والی مشیت کا ذکر ہے — کیونکہ نور اللہ ہی نے دیا تھا اور وہی جسے چاہے دے اور جسے چاہے لے لے۔
۴۔ مثال کا سبق: جو شخص ایمان کا ظاہری دعویٰ رکھے مگر باطن خالی رکھے، اس کی حالت اس شخص جیسی ہے جو ابھی تک روشنی دیکھ کر چل رہا تھا — اچانک اندھیرے میں رہ جاتا ہے۔
۵۔ اس آیت میں ڈھیلا نفاق (محض دکھاوا) کی سزا اور خطرے کی تنبیہ ہے — روشنی سے بچنا نہیں، اسے ہاتھ میں رکھے رکھنا ضروری ہے۔"""
),
25: (
"بہرے، گونگے، اندھے ہیں — پس وہ واپس نہیں لوٹتے۔",
"""۱۔ پچھلی مثال کا نتیجہ بیان ہوا: وہ بہرے ہیں حق کی آواز سننے سے، گونگے ہیں سچ بولنے سے، اور اندھے ہیں ہدایت کی روشنی دیکھنے سے۔
۲۔ حقیقت میں ان کے کان، زبان اور آنکھیں موجود ہیں — مگر ایمان کی راہ میں وہ ہیں جیسے یہ عضو معطل ہوں۔ یہ استعارہ ان کی اندرونی بے حسی کا ہے۔
۳۔ ’’فَهُمْ لَا يَرْجِعُونَ‘‘ — پس وہ واپس نہیں لوٹتے۔ یعنی حق اور توبہ کی طرف پلٹنے کا امکان ان کے لیے ختم ہو چکا — یہ اُس سخت حالت کی علامت ہے جب گمراہی کی عادت دل میں پختہ ہو جائے۔
۴۔ یہ آیت ڈرنا نہیں سمجھانے والی ہے: اگر دل کو مسلسل حق کے مقابل پر ڈالیں تو ضمیر (روح کا آنکھ-کان) کمزور ہوتا چلا جاتا ہے۔ یہی خاموش موت ہے۔
۵۔ دعا یہ ہونی چاہیے: اے اللہ ہمارے دلوں کو مردہ ہونے سے بچا اور حق سننے و دیکھنے کی طاقت قائم رکھ۔"""
),
26: (
"یا ان کی مثال (ایسی ہے) جیسے آسمان سے بارش ہو جس میں اندھیرے ہوں، گرج ہو اور بجلی — وہ بجلی کے کڑکنے سے کان بند کر لیتے ہیں، موت کے خوف سے — اور اللہ کافروں کو گھیرتا ہے۔",
"""۱۔ منافقین کی کیفیت کی دوسری مثال دی گئی: شدید بارش میں — اندھیرا، گرج اور بجلی۔ گونج سن کر کانوں میں انگلیاں ڈال لیتے ہیں — کیونکہ گرج انہیں موت کا احساس دلاتی ہے۔
۲۔ بارش = قرآن کی آیات؛ اندھیرے = شبہات؛ گرج و بجلی = تنبیہ و نصیحت؛ انگلیاں کانوں میں = حق سننے سے گریز۔ منافق ان باتوں سے ڈرتا ہے جو اسے اپنی حقیقت کا احساس دلائیں۔
۳۔ ’’وَاللّٰہُ مُحِیطٌ بِالْکٰفِرِیْنَ‘‘ — اور اللہ کافروں کو گھیرے میں لے رکھا ہے۔ یعنی جہاں بھاگیں، اللہ کی قدرت سے باہر نہیں۔ کفر کرنے والے اللہ کی گرفت سے فرار نہیں پا سکتے۔
۴۔ پہلی مثال (آگ) نے ان کے باطن کی تاریکی دکھائی؛ اس دوسری مثال میں بیرونی حالات کی شدت دکھائی — دونوں صورتوں میں انجام ایک ہی: ہلاکت۔
۵۔ عملی سبق: جب حق کی نصیحت سنیں تو ڈر کر منہ نہ موڑیں — جیسے بجلی سے کانوں میں انگلی ڈالنے والا گرج کی سزا سے تو خیر محفوظ نہیں رہتا۔ قبولیت میں ہی سکون ہے۔"""
),
27: (
"بجلی قریب ہے کہ ان کی آنکھیں اچک لے — جب انہیں روشنی دیتی ہے تو اس میں چلتے ہیں اور جب اندھیرا ہو جاتا ہے تو کھڑے رہ جاتے ہیں۔ اور اگر اللہ چاہتا تو ان کے کانوں اور آنکھوں کو بھی ختم کر دیتا — یقیناً اللہ ہر چیز پر قدرت رکھتا ہے۔",
"""۱۔ دوسری مثال کی تکمیل: بجلی کی چمک اتنی تیز ہے کہ آنکھیں تقریباً اچک لی جائے۔ جب راستے کی کچھ روشنی ملتی ہے تو منافقین چند قدم چلتے ہیں، اور جب اندھیرا چھا جاتا ہے تو وہیں کھڑے رہ جاتے ہیں۔
۲۔ یہ منافق کے عمل کی بڑی تصویر ہے: جب حالات سازگار ہوں (فتح، امن، آسانی) تو مؤمنوں کے ساتھ چلتے ہیں؛ جب حالات مشکل ہوں تو وہیں ڈٹ جاتے یا پیچھے ہٹ جاتے ہیں — ایمان مواقع پر نہیں، ہر حال میں چلنے کا نام ہے۔
۳۔ ’’وَلَوْ شَاءَ اللّٰہُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَارِهِمْ‘‘ — اور اگر اللہ چاہتا تو ان کی سماعت اور بصارت بھی چھین لیتا۔ یعنی ان کو جو کچھ ملا — تھوڑی سی روشنی — وہ بھی صرف اللہ کی مشیت سے تھا؛ اور وہ چاہے تو سب چھین لے۔
۴۔ ’’إِنَّ اللّٰہَ عَلٰی كُلِّ شَیْءٍ قَدِیْرٌ‘‘ — بے شک اللہ ہر چیز پر قادر ہے۔ سب قدرتیں اسی کی ہیں — بندہ مختار ہے مگر انجام کار اختیارات بھی اسی مالک کے ہاتھ میں ہیں۔
۵۔ عملی سبق: سچائی کے ساتھ سختی اور نرمی دونوں میں برابری سے کھڑے رہیں — وقتی سہولت ایمان کا پیمانہ نہیں۔"""
),
}
